  // Color palette descriptions
  if (colorPalette) {
    const paletteDescriptions: Record<ColorPalette, string> = {
      'neutral-earth-tones': 'การจับคู่สีเอิร์ธโทนที่ดูอบอุ่นและมีสไตล์',
